 "content": [{"type": "paragraph", "content": [{"type": "text", "text": "各部分之和不等于总量"}]}]}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#eff6ff", "borderColor": "#3b82f6", "icon": "📊"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "刷题建议：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "按比例分配的关键是\"总量/总比例=每份的值\"。用份数法简化计算。"}]}]}]}$$ AS jsonb), NULL, '数量关系-比例倍数问题-按比例分配的核心知识点和解题方法。', category_node.id, CAST('["数量关系", "比例倍数问题", "按比例分配"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_ratio_distribution", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
